import React, { useState, useEffect } from 'react';
import { getLatestMovies } from '../api/tmdb';

function MovieSlider() {
  const [movies, setMovies] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => {
    const fetchMovies = async () => {
      try {
        const data = await getLatestMovies();
        if (data && data.length > 0) {
          setMovies(data);
        }
      } catch (error) {
        console.error('Failed to fetch movies:', error);
      }
    };
    fetchMovies();
  }, []);

  const handlePrev = () => {
    if (movies.length === 0) return;
    setCurrentIndex((prev) => (prev === 0 ? movies.length - 1 : prev - 1));
  };

  const handleNext = () => {
    if (movies.length === 0) return;
    setCurrentIndex((prev) => (prev === movies.length - 1 ? 0 : prev + 1));
  };

  if (!movies || movies.length === 0) {
    return (
      <div className="flex items-center justify-center min-h-[400px] bg-[#0b090e] text-white/60">
        Loading 3D Curved Gallery...
      </div>
    );
  }

  return (
    <div className="relative w-full min-h-[650px] bg-[#0b090e] text-white flex flex-col items-center justify-center overflow-hidden py-12 select-none">
      
      {/* 배경 네온/글로우(Ambient Glow) 효과 */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[700px] h-[350px] bg-gradient-to-r from-orange-600/15 via-purple-600/15 to-blue-600/15 rounded-full blur-[140px] pointer-events-none" />

      {/* 상단 히어로 텍스트 영역 */}
      <div className="relative z-10 text-center mb-10 px-4">
        <h2 className="text-2xl md:text-3xl font-semibold tracking-tight text-gray-100 mb-2">
          Explore a world where ideas move beyond the screen
        </h2>
        <p className="text-sm text-gray-400">
          Spatial thinking used to test clarity and intent before design decisions are locked.
        </p>
      </div>

      {/* 3D 아치 레이아웃 스테이지 영역 */}
      <div 
        className="relative w-full max-w-5xl h-[420px] flex items-center justify-center"
        style={{ perspective: '1400px' }}
      >
        {movies.map((movie, index) => {
          let offset = (index - currentIndex + movies.length) % movies.length;
          if (offset > movies.length / 2) {
            offset -= movies.length;
          }

          // 수평 기준 아치형 배치 계산
          const spacingX = 240; // 카드 간 수평 간격
          const translateX = offset * spacingX;
          const translateZ = -Math.abs(offset) * 90; // 멀어질수록 뒤로 들어감
          const rotateY = offset * -18; // 양옆으로 갈수록 안쪽으로 회전
          
          const scale = Math.max(1 - Math.abs(offset) * 0.12, 0.7);
          const opacity = Math.abs(offset) > 2.5 ? 0 : 1;

          return (
            <div
              key={movie.id || index}
              onClick={() => setCurrentIndex(index)}
              style={{
                transform: `translateX(${translateX}px) translateZ(${translateZ}px) rotateY(${rotateY}deg) scale(${scale})`,
                zIndex: movies.length - Math.abs(offset),
                opacity: opacity,
                pointerEvents: opacity === 0 ? 'none' : 'auto',
                transition: 'all 0.6s cubic-bezier(0.25, 1, 0.5, 1)',
              }}
              className={`absolute top-1/2 -translate-y-1/2 w-64 h-96 rounded-2xl overflow-hidden cursor-pointer shadow-2xl border ${
                offset === 0 
                  ? 'border-white/20 shadow-[0_0_30px_rgba(255,255,255,0.15)] bg-zinc-900' 
                  : 'border-white/5 bg-zinc-950/80 brightness-75 hover:brightness-90'
              }`}
            >
              <img
                src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`}
                alt={movie.title || 'Movie Poster'}
                className="w-full h-full object-cover pointer-events-none"
              />
            </div>
          );
        })}
      </div>

      {/* 좌우 네비게이션 컨트롤 버튼 및 인디케이터 */}
      <div className="relative z-10 flex items-center gap-6 mt-8">
        <button 
          onClick={handlePrev}
          className="w-10 h-10 rounded-full bg-white/10 border border-white/10 text-white shadow-md flex items-center justify-center hover:bg-white/20 transition active:scale-95 cursor-pointer"
        >
          &larr;
        </button>
        
        <div className="flex gap-2">
          {movies.map((_, idx) => (
            <span 
              key={idx}
              onClick={() => setCurrentIndex(idx)}
              className={`h-2 rounded-full cursor-pointer transition-all ${
                idx === currentIndex ? 'bg-orange-500 w-6' : 'bg-white/20 w-2'
              }`}
            />
          ))}
        </div>

        <button 
          onClick={handleNext}
          className="w-10 h-10 rounded-full bg-white/10 border border-white/10 text-white shadow-md flex items-center justify-center hover:bg-white/20 transition active:scale-95 cursor-pointer"
        >
          &rarr;
        </button>
      </div>

    </div>
  );
}

export default MovieSlider;
